const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',building:'M4 21V3h12v18 M16 9h4v12 M2 21h20 M8 7h4 M8 11h4 M8 15h4 M9 21v-3h2v3',briefcase:'M8 6V3h8v3 M3 6h18v14H3z M3 11a25 25 0 0 0 18 0 M10 12h4',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2 M8 14h2 M14 14h2 M8 18h2',chart:'M3 3v18h18 M7 16V10 M12 16V5 M17 16v-5',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7z M8 12l3 3 5-6',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',arrow:'M4 12h16 M14 6l6 6-6 6',plus:'M12 5v14 M5 12h14',download:'M12 3v12 M7 10l5 5 5-5 M3 16v5h18v-5',more:'M5 12h.01 M12 12h.01 M19 12h.01',logout:'M9 4H4v16h5 M13 7l5 5-5 5 M8 12h13',chevron:'M9 5l7 7-7 7',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M18 6 6 18',edit:'m15 5 4 4 M4 20l4-1L20 7l-4-4L4 15z',archive:'M3 3h18v5H3z M5 8v13h14V8 M10 12h4',print:'M6 9V3h12v6 M6 17H3V9h18v8h-3 M6 14h12v7H6z',menu:'M3 6h18 M3 12h18 M3 18h18',key:'M14 7a5 5 0 1 1-3 8l-6 6H2v-3l6-6a5 5 0 0 1 6-5',trend:'m3 17 6-6 4 4 8-10 M15 5h6v6'};
const icon=(n,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const names={dashboard:'Tổng quan',employees:'Hồ sơ nhân viên',departments:'Phòng ban & chức vụ',contracts:'Hợp đồng lao động',assignments:'Quá trình công tác',leaves:'Nghỉ phép',reports:'Báo cáo nhân sự',settings:'Quản trị hệ thống'};
const roleNames={admin:'Quản trị viên',hr:'Cán bộ nhân sự',manager:'Trưởng phòng',employee:'Nhân viên',director:'Ban giám đốc'};
let leaveYear='',S=null,route=location.hash.slice(1)||'dashboard',tab='',search='',dept='',filter='',page=1,reportType='personnel',reportFrom='',reportTo='',reportDept='';
const canEdit=()=>['admin','hr'].includes(S.user.role);
const canAssign=()=>['admin','hr','director'].includes(S.user.role);
const canReview=l=>['admin','manager'].includes(S.user.role)&&l.employee_id!==S.user.employee_id&&l.status==='Chờ duyệt';
const emp=id=>S.employees.find(e=>e.id===id);
const department=id=>S.departments.find(e=>e.id===id)?.name||'—';
const position=id=>S.positions.find(e=>e.id===id)?.name||'—';
const employeeName=id=>emp(id)?.name||id;
const fmt=v=>v?new Intl.DateTimeFormat('vi-VN').format(new Date(v+'T00:00:00')):'Không xác định';
const money=v=>v==null?'Hạn chế truy cập':new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(v);
const daysUntil=v=>Math.round((Date.parse(v)-Date.parse(S.today))/86400000);
const initials=name=>String(name).split(' ').slice(-2).map(x=>x[0]).join('').toUpperCase();
const avatar=(e,size='')=>`<span class="avatar c${[...String(e?.id)].reduce((a,c)=>a+c.charCodeAt(0),0)%5} ${size}">${esc(initials(e?.name||'?'))}</span>`;
const person=e=>`<div class="person">${avatar(e)}<div><strong>${esc(e?.name||'—')}</strong><small>${esc(e?.email||e?.id||'')}</small></div></div>`;
const badge=s=>`<span class="status ${['Chờ duyệt','Thử việc','Sắp hết hạn','Chưa hiệu lực'].includes(s)?'warn':['Từ chối','Hết hạn','Đã chấm dứt'].includes(s)?'red':['Đã lưu trữ','Đã hủy'].includes(s)?'neutral':''}">${esc(s)}</span>`;
const btn=(action,label,ico='plus',klass='',id='')=>`<button type="button" class="btn ${klass}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''}>${icon(ico)}${label}</button>`;
const textBtn=(action,label,id='',ico='arrow')=>`<button type="button" class="text-btn" data-action="${action}" data-id="${esc(id)}">${label}${icon(ico)}</button>`;
const empty=message=>`<div class="empty">${icon('file')}${message}</div>`;
const options=(rows,value,key='name')=>rows.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(x[key])}</option>`).join('');
const activeEmployees=()=>S.employees.filter(e=>e.status!=='Đã lưu trữ');
const input=(label,name,value='',type='text',attrs='',full=false)=>`<label class="field ${full?'full':''}"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,html,attrs='',full=false)=>`<label class="field ${full?'full':''}"><span>${label}</span><select name="${name}" ${attrs}>${html}</select></label>`;
const choices=(values,v)=>values.map(x=>`<option ${x===v?'selected':''} value="${esc(x)}">${esc(x)}</option>`).join('');
const area=(label,name,value='',required=true)=>`<label class="field full"><span>${label}</span><textarea name="${name}" maxlength="1000" ${required?'required':''}>${esc(value)}</textarea></label>`;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500);}
async function request(path,body,method=body?'POST':'GET'){
  const res=await fetch(path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{})});
  const data=await res.json();if(!res.ok){if(res.status===401&&path!=='/api/login'){S=null;renderLogin();}throw new Error(data.error||'Không thể xử lý yêu cầu.');}return data;
}
async function refresh(){S=await request('/api/state');render();}
function navigate(to){if(location.hash===`#${to}`){route=to;tab='';search='';dept='';filter='';page=1;render();}else location.hash=to;}
function head(title,description,actions='',eyebrow='KHÔNG GIAN NHÂN SỰ'){return `<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></div>`;}
function table(headers,rows,foot=''){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>${foot}`:empty('Chưa có dữ liệu phù hợp.');}
function stat(label,value,unit,ico,foot){return `<div class="stat"><div class="stat-icon">${icon(ico)}</div><div class="stat-label">${label}</div><div class="stat-number">${value}<small>${unit}</small></div><div class="stat-foot">${foot}</div></div>`;}
function tabs(items){return `<div class="tabs">${items.map(x=>`<button data-action="tab" data-id="${x[0]}" class="${tab===x[0]?'active':''}">${x[1]}${x[2]!=null?`<span class="pill">${x[2]}</span>`:''}</button>`).join('')}</div>`;}
function filters(statuses=[]){return `<div class="filters"><input id="list-search" aria-label="Tìm kiếm trong danh sách" placeholder="Tìm tên, mã, email…" value="${esc(search)}"><select id="department-filter" aria-label="Lọc phòng ban"><option value="">Tất cả phòng ban</option>${options(S.departments,dept)}</select>${statuses.length?`<select id="status-filter" aria-label="Lọc trạng thái"><option value="">Tất cả trạng thái</option>${choices(statuses,filter)}</select>`:''}</div>`;}
function matchEmployee(e){const q=search.toLocaleLowerCase('vi');return e&&(!dept||e.department_id===dept)&&(!q||[e.name,e.id,e.email].some(x=>x.toLocaleLowerCase('vi').includes(q)));}
function pagination(n){const total=Math.max(1,Math.ceil(n/8));page=Math.min(page,total);return `<div class="table-footer"><span>${n?`${(page-1)*8+1}–${Math.min(page*8,n)} trong ${n}`:'0'} kết quả</span><div class="pagination">${Array.from({length:total},(_,i)=>`<button data-action="page" data-id="${i+1}" class="${page===i+1?'active':''}" aria-label="Trang ${i+1}">${i+1}</button>`).join('')}</div></div>`;}
function sliceRows(rows){page=Math.min(page,Math.max(1,Math.ceil(rows.length/8)));return rows.slice((page-1)*8,page*8);}
function contractStatus(c){return c.status==='Hiệu lực'&&c.end_date&&daysUntil(c.end_date)<=30?'Sắp hết hạn':c.status;}
function dashboard(){
  const active=activeEmployees(),pending=S.leaves.filter(l=>l.status==='Chờ duyệt'),soon=S.contracts.filter(c=>contractStatus(c)==='Sắp hết hạn'),newcomers=active.filter(e=>e.join_date.slice(0,7)===S.today.slice(0,7));
  const total=active.length,max=Math.max(1,...S.departments.map(d=>active.filter(e=>e.department_id===d.id).length));
  const greeting=`${new Date().getHours()<12?'Chào buổi sáng':new Date().getHours()<18?'Chào buổi chiều':'Chào buổi tối'}, ${esc(S.user.name.split(' ').slice(-2).join(' '))}`;
  return head(greeting,'Một góc nhìn rõ ràng về con người và tổ chức của bạn.',`${btn('export','Xuất báo cáo','download')}${canEdit()?btn('add-employee','Thêm nhân viên','plus','primary'):S.user.role==='director'?btn('go-reports','Xem báo cáo','chart','primary'):btn('add-leave','Đăng ký nghỉ phép','plus','primary')}`,'TỔNG QUAN HỆ THỐNG')+
  `<div class="stats">${stat('Tổng nhân sự',total,'nhân viên','people',`<strong>${newcomers.length} nhân viên mới</strong> trong tháng này`)}${stat('Phòng ban',S.departments.length,'phòng ban','building','Cơ cấu tổ chức hiện tại')}${stat('Hợp đồng sắp hết hạn',soon.length,'hợp đồng','file','Cần theo dõi trong <strong>30 ngày tới</strong>')}${stat('Đơn nghỉ chờ duyệt',pending.length,'đơn','calendar','Cập nhật từ các đơn nghỉ phép')}</div>`+
  `<div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>Phân bổ nhân sự</h2><p>Nhân viên đang làm việc theo phòng ban</p></div><span class="chip">${total} nhân viên</span></div><div class="card-body"><div class="distribution">${S.departments.map((d,i)=>{const n=active.filter(e=>e.department_id===d.id).length;return `<span>${esc(d.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%;opacity:${1-i*.1}"></div></div><span class="bar-value">${n.toString().padStart(2,'0')}</span>`;}).join('')}</div><div class="chart-legend"><span><i class="legend-dot"></i>Nhân sự hiện tại</span>${textBtn('go-departments','Xem cơ cấu tổ chức')}</div></div></section>
  <section class="card"><div class="card-head"><div><h2>Cần bạn quan tâm</h2><p>Những việc cần theo dõi hôm nay</p></div>${icon('more')}</div><div class="card-body alert-list">${soon.slice(0,2).map(c=>`<div class="alert-item"><span class="alert-icon">${icon('clock')}</span><div><strong>Hợp đồng còn ${daysUntil(c.end_date)} ngày</strong><p>${esc(employeeName(c.employee_id))} · ${esc(c.id)}</p>${textBtn('contract-detail','Xem hợp đồng',c.id)}</div></div>`).join('')}${pending.length?`<div class="alert-item"><span class="alert-icon" style="background:#edf3ed;color:#6a8c68">${icon('calendar')}</span><div><strong>${pending.length} đơn nghỉ phép đang chờ</strong><p>Theo dõi và xử lý đơn nghỉ phép của nhân viên.</p>${textBtn('go-leaves','Xem danh sách đơn')}</div></div>`:''}${!soon.length&&!pending.length?empty('Mọi việc đã được cập nhật.'):''}</div></section></div>
  <section class="card"><div class="card-head"><div><h2>Nhân sự trong tổ chức</h2><p>Hồ sơ và trạng thái làm việc hiện tại</p></div>${textBtn('go-employees','Xem tất cả')}</div><div style="height:16px"></div>${table(['Nhân viên','Mã nhân viên','Phòng ban','Chức vụ','Trạng thái',''],active.slice(0,5).map(e=>employeeRow(e,false)))}</section>`;
}
function employeeRow(e,editable=true){return `<tr><td>${person(e)}</td><td>${esc(e.id)}</td><td>${esc(department(e.department_id))}</td><td>${esc(position(e.position_id))}</td><td>${badge(e.status)}</td><td>${textBtn('employee-detail','Chi tiết',e.id,'chevron')}${editable&&canEdit()&&e.status!=='Đã lưu trữ'?textBtn('edit-employee','Sửa',e.id,'edit'):''}</td></tr>`;}
function employees(){
  if(!tab)tab='active';const rows=S.employees.filter(e=>(tab==='archived'?e.status==='Đã lưu trữ':e.status!=='Đã lưu trữ')&&matchEmployee(e)&&(!filter||e.status===filter));
  return head('Hồ sơ nhân viên','Quản lý thông tin, tra cứu và lưu trữ hồ sơ nhân sự.',`${btn('export','Xuất danh sách','download')}${canEdit()?btn('add-employee','Thêm nhân viên','plus','primary'):''}`)+`<section class="card"><div class="panel-toolbar">${tabs([['active','Đang làm việc',activeEmployees().length],['archived','Đã lưu trữ',S.employees.filter(e=>e.status==='Đã lưu trữ').length]])}${filters(['Đang làm việc','Thử việc'])}</div>${table(['Nhân viên','Mã nhân viên','Phòng ban','Chức vụ','Trạng thái','Thao tác'],sliceRows(rows).map(e=>employeeRow(e)),pagination(rows.length))}</section>`;
}
function departments(){
  if(!tab)tab='departments';const isDept=tab==='departments';
  return head('Phòng ban & chức vụ','Xây dựng cơ cấu tổ chức và danh mục chức danh.',canEdit()?btn(isDept?'add-department':'add-position',isDept?'Thêm phòng ban':'Thêm chức vụ','plus','primary'):'')+
  `<div class="section-gap">${tabs([['departments','Phòng ban',S.departments.length],['positions','Chức vụ',S.positions.length]])}</div>`+
  (isDept?`<div class="department-grid">${S.departments.map(d=>{const members=activeEmployees().filter(e=>e.department_id===d.id);return `<section class="card department-card"><div style="display:flex;justify-content:space-between"><span class="stat-icon" style="position:static">${icon('building')}</span><span class="chip">${esc(d.id)}</span></div><h3>${esc(d.name)}</h3><p>${esc(d.description||'Chưa có mô tả phòng ban.')}</p><div class="avatars">${members.slice(0,5).map(e=>avatar(e)).join('')}</div><div class="dept-bottom"><span>${members.length} nhân viên</span><div>${textBtn('department-members','Xem',d.id)}${canEdit()?textBtn('edit-department','Sửa',d.id,'edit'):''}</div></div></section>`;}).join('')}</div>`:
  `<section class="card">${table(['Mã chức vụ','Tên chức vụ','Cấp bậc','Mô tả','Nhân viên',''],S.positions.map(p=>`<tr><td>${esc(p.id)}</td><td><strong>${esc(p.name)}</strong></td><td>${p.level}</td><td>${esc(p.description||'—')}</td><td>${activeEmployees().filter(e=>e.position_id===p.id).length}</td><td>${canEdit()?textBtn('edit-position','Chỉnh sửa',p.id,'edit'):''}</td></tr>`))}</section>`);
}
function contracts(){
  if(!tab)tab='all';const rows=S.contracts.filter(c=>matchEmployee(emp(c.employee_id))&&(!filter||contractStatus(c)===filter)&&(tab!=='expiring'||contractStatus(c)==='Sắp hết hạn'));
  return head('Hợp đồng lao động','Theo dõi thời hạn, gia hạn và quản lý vòng đời hợp đồng.',`${btn('export','Xuất danh sách','download')}${canEdit()?btn('add-contract','Lập hợp đồng','plus','primary'):''}`)+
  `<section class="card"><div class="panel-toolbar">${tabs([['all','Tất cả hợp đồng',S.contracts.length],['expiring','Sắp hết hạn',S.contracts.filter(c=>contractStatus(c)==='Sắp hết hạn').length]])}${filters(['Hiệu lực','Sắp hết hạn','Hết hạn','Chưa hiệu lực','Đã chấm dứt'])}</div>${table(['Hợp đồng','Nhân viên','Loại hợp đồng','Thời hạn','Mức lương / tháng','Trạng thái',''],sliceRows(rows).map(c=>`<tr><td><strong>${esc(c.id)}</strong></td><td>${person(emp(c.employee_id))}</td><td>${esc(c.type)}</td><td>${fmt(c.start_date)}<br><small>đến ${fmt(c.end_date)}</small></td><td>${money(c.salary)}</td><td>${badge(contractStatus(c))}</td><td>${textBtn('contract-detail','Chi tiết',c.id,'chevron')}</td></tr>`),pagination(rows.length))}</section>`;
}
function assignments(){
  const rows=S.assignments.filter(a=>matchEmployee(emp(a.employee_id)));
  return head('Quá trình công tác','Lưu vết điều chuyển, bổ nhiệm và quyết định nhân sự.',`${btn('export','Xuất lịch sử','download')}${canAssign()?btn('add-assignment','Ghi nhận công tác','plus','primary'):''}`)+
  `<div class="info-banner">Mỗi thay đổi phòng ban hoặc chức vụ được gắn với một quyết định và cập nhật đồng thời vào hồ sơ nhân viên.</div><section class="card"><div class="panel-toolbar"><strong style="font-size:12px">Lịch sử biến động</strong>${filters()}</div>${table(['Nhân viên','Loại biến động','Phòng ban','Chức vụ','Hiệu lực','Quyết định',''],sliceRows(rows).map(a=>`<tr><td>${person(emp(a.employee_id))}</td><td>${badge(a.type)}</td><td>${esc(department(a.old_department_id))}<br>→ ${esc(department(a.new_department_id))}</td><td>${esc(position(a.old_position_id))}<br>→ ${esc(position(a.new_position_id))}</td><td>${fmt(a.effective_date)}</td><td>${esc(S.decisions.find(d=>d.id===a.decision_id)?.number)}</td><td>${textBtn('decision-detail','Xem',a.decision_id,'chevron')}</td></tr>`),pagination(rows.length))}</section>`;
}
function leaves(){
  if(!tab)tab='requests';let rows=S.leaves.filter(l=>matchEmployee(emp(l.employee_id))&&(!filter||l.status===filter));
  const year=Number(leaveYear||S.today.slice(0,4));
  return head('Công tác & nghỉ phép','Đăng ký nghỉ, xử lý phê duyệt và theo dõi quỹ phép.',`${btn('export','Xuất dữ liệu','download')}${S.user.role!=='director'?btn('add-leave','Đăng ký nghỉ phép','plus','primary'):''}`)+
  `<div class="info-banner">Quy ước bài tập: số ngày nghỉ tính theo ngày lịch, gồm cả ngày bắt đầu và ngày kết thúc. Chỉ loại “Phép năm” đã duyệt được trừ vào quỹ phép. Quỹ mặc định: 12 ngày/năm.</div><section class="card"><div class="panel-toolbar">${tabs([['requests','Đơn nghỉ phép',S.leaves.length],['balances','Quỹ phép '+year]])}${tab==='balances'?`<input id="leave-year" aria-label="Năm quỹ phép" type="number" min="2000" max="2100" value="${year}">`:''}${filters(tab==='requests'?['Chờ duyệt','Đã duyệt','Từ chối','Đã hủy']:[])}</div>${tab==='balances'?table(['Nhân viên','Phòng ban','Năm','Tổng phép','Đã sử dụng','Còn lại',''],S.balances.filter(b=>b.year===year&&matchEmployee(emp(b.employee_id))&&emp(b.employee_id).status!=='Đã lưu trữ').map(b=>`<tr><td>${person(emp(b.employee_id))}</td><td>${esc(department(emp(b.employee_id).department_id))}</td><td>${b.year}</td><td>${b.total} ngày</td><td>${b.used} ngày</td><td><strong>${b.remaining} ngày</strong></td><td>${canEdit()?textBtn('edit-balance','Điều chỉnh',b.employee_id,'edit'):''}</td></tr>`)):
  table(['Nhân viên','Loại nghỉ','Thời gian','Số ngày','Trạng thái',''],sliceRows(rows).map(l=>`<tr><td>${person(emp(l.employee_id))}</td><td>${esc(S.leaveTypes.find(t=>t.id===l.type_id)?.name)}</td><td>${fmt(l.start_date)} – ${fmt(l.end_date)}</td><td>${l.days} ngày</td><td>${badge(l.status)}</td><td>${textBtn('leave-detail',canReview(l)?'Xử lý':'Chi tiết',l.id,'chevron')}</td></tr>`),pagination(rows.length))}</section>`;
}
function filteredReport(){
  const match=(eid,date)=>{const e=emp(eid);return e&&(!reportDept||e.department_id===reportDept)&&(!reportFrom||date>=reportFrom)&&(!reportTo||date<=reportTo);};
  if(reportType==='movements')return {headers:['Nhân viên','Loại biến động','Phòng ban cũ','Phòng ban mới','Chức vụ mới','Ngày hiệu lực'],rows:S.assignments.filter(a=>match(a.employee_id,a.effective_date)).map(a=>[employeeName(a.employee_id),a.type,department(a.old_department_id),department(a.new_department_id),position(a.new_position_id),a.effective_date])};
  if(reportType==='contracts')return {headers:['Mã hợp đồng','Nhân viên','Loại hợp đồng','Ngày bắt đầu','Ngày kết thúc','Mức lương','Trạng thái'],rows:S.contracts.filter(c=>match(c.employee_id,c.start_date)).map(c=>[c.id,employeeName(c.employee_id),c.type,c.start_date,c.end_date||'Không xác định',c.salary??'Hạn chế truy cập',contractStatus(c)])};
  if(reportType==='leaves')return {headers:['Nhân viên','Loại nghỉ','Từ ngày','Đến ngày','Số ngày','Trạng thái','Người duyệt'],rows:S.leaves.filter(l=>match(l.employee_id,l.start_date)).map(l=>[employeeName(l.employee_id),S.leaveTypes.find(t=>t.id===l.type_id)?.name,l.start_date,l.end_date,l.days,l.status,l.approver_id?employeeName(l.approver_id):'—'])};
  return {headers:['Mã nhân viên','Họ tên','Giới tính','Phòng ban','Chức vụ','Ngày vào làm','Trạng thái'],rows:S.employees.filter(e=>match(e.id,e.join_date)).map(e=>[e.id,e.name,e.gender,department(e.department_id),position(e.position_id),e.join_date,e.status])};
}
function reports(){
  const data=filteredReport();const labels={personnel:'Thống kê nhân sự',movements:'Biến động nhân sự',contracts:'Báo cáo hợp đồng',leaves:'Báo cáo nghỉ phép'};
  return head('Báo cáo nhân sự','Tổng hợp dữ liệu để theo dõi và hỗ trợ ra quyết định.',`${btn('print','In báo cáo','print')}${btn('export','Tải báo cáo CSV','download','primary')}`)+
  `<section class="card section-gap"><div class="panel-toolbar"><div class="filters"><select id="report-type" aria-label="Loại báo cáo">${Object.entries(labels).map(([id,name])=>`<option value="${id}" ${reportType===id?'selected':''}>${name}</option>`).join('')}</select><select id="report-dept" aria-label="Phòng ban báo cáo"><option value="">Tất cả phòng ban</option>${options(S.departments,reportDept)}</select><label style="font-size:10px;color:var(--muted)">Từ <input id="report-from" type="date" value="${reportFrom}" aria-label="Từ ngày"></label><label style="font-size:10px;color:var(--muted)">Đến <input id="report-to" type="date" value="${reportTo}" aria-label="Đến ngày"></label>${textBtn('reset-report','Đặt lại','','close')}</div></div></section>`+
  `<div class="summary-cards">${stat('Số bản ghi',data.rows.length,'kết quả','chart','Theo bộ lọc đang chọn')}${stat('Phạm vi phòng ban',reportDept?1:S.departments.length,'phòng ban','building',reportDept?esc(department(reportDept)):'Tất cả phòng ban được phép xem')}${stat('Ngày lập báo cáo',S.today.slice(8,10)+'/'+S.today.slice(5,7),S.today.slice(0,4),'calendar',esc(S.user.name))}</div>`+
  `<section class="card"><div class="card-head"><div><h2>${labels[reportType]}</h2><p>${reportFrom?fmt(reportFrom):'Từ đầu dữ liệu'} → ${reportTo?fmt(reportTo):'Mới nhất'}</p></div><span class="chip">${data.rows.length} bản ghi</span></div><div style="height:18px"></div>${table(data.headers,data.rows.map(row=>`<tr>${row.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`))}</section><p class="report-note">Bộ lọc thời gian dùng ${reportType==='personnel'?'ngày vào làm':reportType==='movements'?'ngày hiệu lực':reportType==='contracts'?'ngày bắt đầu hợp đồng':'ngày bắt đầu nghỉ'}. Phòng ban được xác định theo hồ sơ hiện tại. Dữ liệu hiển thị theo quyền của tài khoản.</p>`;
}
function settings(){
  if(S.user.role!=='admin')return head('Tài khoản của tôi','Quản lý thông tin đăng nhập và mật khẩu.',btn('change-password','Đổi mật khẩu','key'))+`<section class="card"><div class="card-body"><strong>${esc(S.user.name)}</strong><p class="notice">Tên đăng nhập: ${esc(S.user.username)} · Vai trò: ${roleNames[S.user.role]}</p></div></section>`;
  if(!tab)tab='users';
  return head('Quản trị hệ thống','Quản lý quyền truy cập và theo dõi thao tác trong hệ thống.',`${btn('change-password','Đổi mật khẩu','key')}${btn('add-user','Tạo tài khoản','plus','primary')}`)+
  `<section class="card"><div class="panel-toolbar">${tabs([['users','Tài khoản',S.users.length],['audit','Nhật ký hoạt động']])}</div>${tab==='users'?table(['Tên đăng nhập','Nhân viên','Vai trò','Trạng thái',''],S.users.map(u=>`<tr><td><strong>${esc(u.username)}</strong></td><td>${esc(u.name)}</td><td>${roleNames[u.role]}</td><td>${badge(u.active?'Đang hoạt động':'Đã hủy')}</td><td>${u.id!==S.user.id?textBtn('toggle-user',u.active?'Khóa tài khoản':'Mở khóa',u.id,'shield'):''}</td></tr>`)):table(['Thời gian','Tài khoản','Hoạt động','Đối tượng'],S.audit.map(a=>`<tr><td>${esc(new Date(a.created_at).toLocaleString('vi-VN'))}</td><td>${esc(a.username||'Hệ thống')}</td><td class="audit">${esc(a.action)}</td><td class="audit">${esc(a.target)}</td></tr>`))}</section>`;
}
function render(){
  if(!S)return renderLogin();if(!names[route])route='dashboard';
  const pending=S.leaves.filter(l=>l.status==='Chờ duyệt').length;
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#dashboard"><span class="brand-mark">p</span><div><strong>PeopleOps<span style="color:#73a08a">.</span></strong><small>People · Work · Together</small></div></a><div class="workspace"><span class="avatar">16</span><div><strong>Không gian nhân sự</strong><small>Nhóm 16 · Bản học tập</small></div>${icon('chevron')}</div><p class="nav-label">QUẢN LÝ</p><nav class="nav">${Object.entries(names).filter(([id])=>id!=='settings').map(([id,name],i)=>`<a href="#${id}" class="${route===id?'active':''}" ${route===id?'aria-current="page"':''}>${icon(['grid','people','building','file','briefcase','calendar','chart'][i])}${name}${id==='leaves'&&pending?`<span class="count">${pending}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav"><a href="#settings" class="${route==='settings'?'active':''}">${icon('shield')}${S.user.role==='admin'?'Quản trị hệ thống':'Tài khoản của tôi'}</a></nav><div class="demo-note"><strong>Con người là trọng tâm.</strong>Mỗi hồ sơ, một hành trình.<br>Cùng xây dựng tổ chức tốt hơn.</div><div class="user-profile">${avatar(emp(S.user.employee_id))}<div style="flex:1"><strong>${esc(S.user.name)}</strong><small>${roleNames[S.user.role]}</small></div><button class="icon-btn" data-action="logout" title="Đăng xuất" aria-label="Đăng xuất">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Mở menu">${icon('menu')}</button><div class="breadcrumb">Không gian làm việc ${icon('chevron')}<strong>${names[route]}</strong></div><div class="topbar-right"><form id="global-search" class="searchbox">${icon('search')}<input name="q" placeholder="Tìm kiếm nhân viên…" aria-label="Tìm kiếm nhân viên"><kbd>↵</kbd></form><span class="date-label" style="font-size:11px;color:#8d998f">${fmt(S.today)}</span><button class="icon-btn ${pending?'notification':''}" data-action="go-leaves" title="Thông báo nghỉ phép" aria-label="Thông báo nghỉ phép">${icon('bell')}</button>${avatar(emp(S.user.employee_id))}</div></header><div class="content">${({dashboard,employees,departments,contracts,assignments,leaves,reports,settings}[route])()}<footer class="page-footer"><span>© ${S.today.slice(0,4)} PeopleOps · Hệ thống quản lý nhân sự</span><span>Nhóm 16 · Dữ liệu lưu tại máy</span></footer></div></main></div>`;
}
function renderLogin(){
  $('#modal').close();$('#app').innerHTML=`<main class="login-page"><section class="login-intro"><div class="brand"><span class="brand-mark">p</span><div><strong>PeopleOps.</strong><small>People · Work · Together</small></div></div><div><p class="eyebrow" style="color:#a7c5ac">KHÔNG GIAN QUẢN LÝ NHÂN SỰ</p><h1>Đồng hành cùng<br>mỗi hành trình.</h1><p>Kết nối hồ sơ, công việc và con người trong một không gian quản lý thống nhất.</p></div><div class="orb"></div><div class="intro-foot">NHÓM 16 &nbsp; / &nbsp; HỆ THỐNG THÔNG TIN QUẢN LÝ</div></section><section class="login-form-wrap"><div class="login-form"><p class="eyebrow">CHÀO MỪNG TRỞ LẠI</p><h2>Đăng nhập hệ thống</h2><p>Bắt đầu ngày làm việc với mọi thông tin nhân sự trong tầm tay.</p><form id="login-form"><div class="form-error" id="login-error" role="alert"></div>${input('Tên đăng nhập','username','admin','text','required autocomplete="username" maxlength="50"')}${input('Mật khẩu','password','','password','required autocomplete="current-password"')}<button class="btn primary" type="submit">Đăng nhập ${icon('arrow')}</button></form><div class="demo-credentials">Tài khoản mẫu · Mật khẩu chung <code>Demo@12345</code><div class="demo-buttons">${[['admin','Quản trị'],['nhansu','Nhân sự'],['truongphong','Trưởng phòng'],['nhanvien','Nhân viên'],['giamdoc','Giám đốc']].map(([id,n])=>`<button data-action="demo-account" data-id="${id}">${n}</button>`).join('')}</div><p style="margin-bottom:0">Dữ liệu minh họa được tạo khi chạy lần đầu.<br>Bạn có thể đổi mật khẩu sau khi đăng nhập.</p></div></div></section></main>`;
}
function showModal(title,body,{form='',submit='Lưu thông tin',footer='',wide=false}={}){
  const modal=$('#modal');modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-btn" type="button" data-action="close-modal" aria-label="Đóng">${icon('close')}</button></div>${form?`<form id="modal-form" data-kind="${form}">`:''}<div class="modal-body"><div id="modal-error" class="form-error" role="alert"></div>${body}</div><div class="modal-actions">${footer||`${btn('close-modal','Đóng','close')}${form?`<button class="btn primary" type="submit">${submit}</button>`:''}`}</div>${form?'</form>':''}`;modal.style.maxWidth=wide?'800px':'660px';if(!modal.open)modal.showModal();
}
function employeeForm(e){
  const isEdit=!!e;e=e||{id:'',name:'',gender:'Nam',join_date:S.today,status:'Đang làm việc',department_id:S.departments[0]?.id,position_id:S.positions.find(p=>p.id==='CV01')?.id};
  showModal(isEdit?'Cập nhật hồ sơ':'Thêm nhân viên mới',`<p class="notice">${isEdit?'Để thay đổi phòng ban hoặc chức vụ, dùng mục Quá trình công tác.':'Các trường có dấu * là bắt buộc. Hồ sơ mới được cấp quỹ phép mặc định 12 ngày/năm.'}</p><div class="form-grid">${input('Mã nhân viên *','id',e.id,'text',`${isEdit?'readonly':'required'} maxlength="25" pattern="[A-Za-z0-9_-]+"`)}${input('Họ và tên *','name',e.name,'text','required maxlength="120"')}${input('Ngày sinh *','birth_date',e.birth_date,'date',`required max="${S.today}"`)}${select('Giới tính *','gender',choices(['Nam','Nữ','Khác'],e.gender))}${input('Số điện thoại *','phone',e.phone,'tel','required maxlength="20"')}${input('Email *','email',e.email,'email','required maxlength="150"')}${input('Ngày vào làm *','join_date',e.join_date,'date','required')}${select('Trạng thái *','status',choices(['Đang làm việc','Thử việc'],e.status))}${select('Phòng ban *','department_id',options(S.departments,e.department_id),isEdit?'disabled':'required')}${select('Chức vụ *','position_id',options(S.positions,e.position_id),isEdit?'disabled':'required')}${input('Địa chỉ','address',e.address,'text','maxlength="500"',true)}<input type="hidden" name="editing" value="${isEdit?esc(e.id):''}"></div>`,{form:'employee'});
}
function employeeDetail(e){
  const balance=S.balances.find(b=>b.employee_id===e.id&&b.year===Number(leaveYear||S.today.slice(0,4)));
  showModal('Hồ sơ nhân viên',`<div class="detail-header">${avatar(e,'lg')}<div><h3>${esc(e.name)}</h3><p>${esc(e.id)} · ${esc(position(e.position_id))}</p><div style="margin-top:10px">${badge(e.status)}</div></div></div><dl class="detail-grid">${[['Phòng ban',department(e.department_id)],['Ngày vào làm',fmt(e.join_date)],['Ngày sinh',fmt(e.birth_date)],['Giới tính',e.gender],['Email',e.email],['Số điện thoại',e.phone],['Địa chỉ',e.address||'—'],['Phép năm còn lại',balance?balance.remaining+' / '+balance.total+' ngày':'—'],...(e.archived_date?[['Ngày lưu trữ',fmt(e.archived_date)]]:[])].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="detail-section"><h3>Hợp đồng lao động</h3>${S.contracts.filter(c=>c.employee_id===e.id).map(c=>`<div class="detail-row"><span><strong>${esc(c.id)}</strong><br><small>${fmt(c.start_date)} → ${fmt(c.end_date)}</small></span>${badge(contractStatus(c))}${textBtn('contract-detail','Xem',c.id)}</div>`).join('')||'<p class="notice">Chưa có hợp đồng.</p>'}<h3>Lịch sử công tác</h3>${S.assignments.filter(a=>a.employee_id===e.id).map(a=>`<div class="detail-row"><span>${esc(a.type)} · ${fmt(a.effective_date)}<br><small>${esc(department(a.old_department_id))} → ${esc(department(a.new_department_id))}<br>${esc(position(a.old_position_id))} → ${esc(position(a.new_position_id))}</small></span>${textBtn('decision-detail','Quyết định',a.decision_id)}</div>`).join('')||'<p class="notice">Chưa có biến động công tác.</p>'}</div>`,{footer:`${btn('close-modal','Đóng','close')}${canEdit()?(e.status==='Đã lưu trữ'?btn('restore-employee','Khôi phục','archive','primary',e.id):`${btn('archive-employee','Lưu trữ hồ sơ','archive','danger',e.id)}${btn('edit-employee','Chỉnh sửa','edit','primary',e.id)}`):''}`});
}
function catalogForm(kind,item){
  const d=kind==='department',edit=!!item;item=item||{id:'',name:'',description:'',founded_date:S.today,level:2};
  showModal(`${edit?'Chỉnh sửa':'Thêm'} ${d?'phòng ban':'chức vụ'}`,`<div class="form-grid">${input('Mã *','id',item.id,'text',`required ${edit?'readonly':''} maxlength="25" pattern="[A-Za-z0-9_-]+"`)}${input('Tên *','name',item.name,'text','required maxlength="120"')}${d?input('Ngày thành lập *','founded_date',item.founded_date,'date','required'):input('Cấp bậc *','level',item.level,'number','required min="1" max="10" step="1"')}${area('Mô tả','description',item.description,false)}<input type="hidden" name="editing" value="${edit?esc(item.id):''}"></div>`,{form:kind,footer:edit?`${btn('delete-'+kind,'Xóa danh mục','archive','danger',item.id)}${btn('close-modal','Đóng','close')}<button class="btn primary" type="submit">Lưu thay đổi</button>`:''});
}
function contractForm(){showModal('Lập hợp đồng lao động',`<div class="form-grid">${input('Mã hợp đồng *','id','','text','required maxlength="30"')}${select('Nhân viên *','employee_id',options(activeEmployees(),''),'required')}${select('Loại hợp đồng *','type',choices(['Thử việc','Xác định thời hạn','Không xác định thời hạn'],'Xác định thời hạn'))}${input('Mức lương tháng (VND) *','salary','','number','required min="1" max="100000000000" step="1"')}${input('Ngày bắt đầu *','start_date',S.today,'date','required')}${input('Ngày kết thúc','end_date','','date','')}<p class="notice full">Hợp đồng có thời hạn cần ngày kết thúc. Không cho phép các hợp đồng chưa chấm dứt trùng khoảng thời gian.</p></div>`,{form:'contract'});}
function contractDetail(c){
  const ex=S.extensions.filter(e=>e.contract_id===c.id);
  showModal('Chi tiết hợp đồng',`<div class="detail-header"><span class="avatar lg">${icon('file')}</span><div><h3>${esc(c.id)}</h3><p>${esc(employeeName(c.employee_id))}</p><div style="margin-top:10px">${badge(contractStatus(c))}</div></div></div><dl class="detail-grid">${[['Loại hợp đồng',c.type],['Mức lương / tháng',money(c.salary)],['Ngày bắt đầu',fmt(c.start_date)],['Ngày kết thúc',fmt(c.end_date)],...(c.terminated_date?[['Ngày chấm dứt',fmt(c.terminated_date)],['Lý do',c.termination_reason]]:[])].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="detail-section"><h3>Lịch sử gia hạn (${ex.length})</h3>${ex.map(e=>`<div class="detail-row"><div><strong>Lần ${e.sequence} · ${fmt(e.created_date)}</strong><br>${fmt(e.old_end_date)} → ${fmt(e.new_end_date)}<br><small>${esc(e.reason)}</small></div></div>`).join('')||'<p class="notice">Chưa có lần gia hạn nào.</p>'}</div>`,{footer:`${btn('close-modal','Đóng','close')}${canEdit()&&c.status!=='Đã chấm dứt'?`${btn('terminate-contract','Chấm dứt','close','danger',c.id)}${c.end_date?btn('extend-contract','Gia hạn hợp đồng','calendar','primary',c.id):''}`:''}`});
}
function assignmentForm(){showModal('Ghi nhận công tác',`<p class="notice">Lưu quyết định và cập nhật phòng ban/chức vụ trong cùng một giao dịch. Nhập quyết định đã có hiệu lực đến hôm nay.</p><div class="form-grid">${select('Nhân viên *','employee_id',options(activeEmployees(),''),'required',true)}${select('Loại biến động *','type',choices(['Điều chuyển','Bổ nhiệm','Điều chuyển và bổ nhiệm']))}${input('Số quyết định *','number','','text','required maxlength="60"')}${select('Phòng ban mới *','new_department_id',options(S.departments,''),'required')}${select('Chức vụ mới *','new_position_id',options(S.positions,''),'required')}${input('Ngày ký *','signed_date',S.today,'date',`required max="${S.today}"`)}${input('Ngày hiệu lực *','effective_date',S.today,'date',`required max="${S.today}"`)}${input('Người ký *','signer','','text','required maxlength="120"',true)}${area('Nội dung / lý do *','reason')}</div>`,{form:'assignment'});}
function leaveForm(){const own=['employee','manager'].includes(S.user.role);showModal('Đăng ký nghỉ phép',`<p class="notice">Số ngày tính theo ngày lịch. Đơn nghỉ qua năm cần tách thành hai đơn. Phép năm chỉ được trừ sau khi duyệt.</p><div class="form-grid">${own?`<input type="hidden" name="employee_id" value="${S.user.employee_id}"><p class="notice full">Nhân viên: <strong>${esc(S.user.name)}</strong></p>`:select('Nhân viên *','employee_id',options(activeEmployees(),S.user.employee_id),'required',true)}${select('Loại nghỉ *','type_id',options(S.leaveTypes,''),'required',true)}${input('Từ ngày *','start_date',S.today,'date',`required min="${S.today}"`)}${input('Đến ngày *','end_date',S.today,'date',`required min="${S.today}"`)}${area('Lý do nghỉ *','reason')}</div>`,{form:'leave',submit:'Gửi đơn nghỉ phép'});}
function leaveDetail(l){
  const own=l.employee_id===S.user.employee_id,canCancel=l.status==='Chờ duyệt'&&(own||canEdit());
  showModal('Chi tiết đơn nghỉ phép',`<div class="detail-header">${avatar(emp(l.employee_id),'lg')}<div><h3>${esc(employeeName(l.employee_id))}</h3><p>${esc(l.id)}</p></div></div><dl class="detail-grid">${[['Loại nghỉ',S.leaveTypes.find(t=>t.id===l.type_id)?.name],['Trạng thái',l.status],['Từ ngày',fmt(l.start_date)],['Đến ngày',fmt(l.end_date)],['Số ngày',l.days+' ngày'],['Ngày nộp',fmt(l.submitted_date)],['Lý do',l.reason],['Người duyệt',l.approver_id?employeeName(l.approver_id):'Chưa xử lý'],...(l.approved_date?[['Ngày xử lý',fmt(l.approved_date)]]:[]),...(l.review_note?[['Ghi chú xử lý',l.review_note]]:[])].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`,{footer:`${btn('close-modal','Đóng','close')}${canCancel?btn('cancel-leave','Hủy đơn','close','danger',l.id):''}${canReview(l)?`${btn('reject-leave','Từ chối','close','danger',l.id)}${btn('approve-leave','Duyệt đơn','check','primary',l.id)}`:''}`});
}
function confirmAction(title,message,action,id,label='Xác nhận'){showModal(title,`<p class="notice">${esc(message)}</p>`,{footer:`${btn('close-modal','Quay lại','close')}${btn(action,label,'check','primary',id)}`});}
async function mutate(path,body={},method='POST',message='Đã lưu thông tin.'){await request(path,body,method);$('#modal').close();await refresh();toast(message);}
function exportData(){
  let data;if(route==='reports')data=filteredReport();else if(route==='contracts')data={headers:['Mã hợp đồng','Nhân viên','Loại','Bắt đầu','Kết thúc','Mức lương','Trạng thái'],rows:S.contracts.filter(c=>matchEmployee(emp(c.employee_id))&&(!filter||contractStatus(c)===filter)&&(tab!=='expiring'||contractStatus(c)==='Sắp hết hạn')).map(c=>[c.id,employeeName(c.employee_id),c.type,c.start_date,c.end_date,c.salary??'',contractStatus(c)])};
  else if(route==='assignments')data={headers:['Nhân viên','Loại','Phòng ban cũ','Phòng ban mới','Chức vụ cũ','Chức vụ mới','Hiệu lực'],rows:S.assignments.filter(a=>matchEmployee(emp(a.employee_id))).map(a=>[employeeName(a.employee_id),a.type,department(a.old_department_id),department(a.new_department_id),position(a.old_position_id),position(a.new_position_id),a.effective_date])};
  else if(route==='leaves')data=tab==='balances'?{headers:['Nhân viên','Năm','Tổng phép','Đã nghỉ','Còn lại'],rows:S.balances.filter(b=>b.year===Number(leaveYear||S.today.slice(0,4))&&matchEmployee(emp(b.employee_id))&&emp(b.employee_id).status!=='Đã lưu trữ').map(b=>[employeeName(b.employee_id),b.year,b.total,b.used,b.remaining])}:{headers:['Nhân viên','Loại nghỉ','Từ ngày','Đến ngày','Số ngày','Trạng thái','Lý do'],rows:S.leaves.filter(l=>matchEmployee(emp(l.employee_id))&&(!filter||l.status===filter)).map(l=>[employeeName(l.employee_id),S.leaveTypes.find(t=>t.id===l.type_id)?.name,l.start_date,l.end_date,l.days,l.status,l.reason])};
  else data={headers:['Mã nhân viên','Họ tên','Ngày sinh','Giới tính','Email','Điện thoại','Phòng ban','Chức vụ','Ngày vào làm','Trạng thái'],rows:S.employees.filter(e=>route==='dashboard'||((tab==='archived'?e.status==='Đã lưu trữ':e.status!=='Đã lưu trữ')&&matchEmployee(e)&&(!filter||e.status===filter))).map(e=>[e.id,e.name,e.birth_date,e.gender,e.email,e.phone,department(e.department_id),position(e.position_id),e.join_date,e.status])};
  const csv='\uFEFF'+[data.headers,...data.rows].map(row=>row.map(v=>{let s=String(v??'');if(/^[=+\-@\t\r\n]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');
  const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`peopleops-${route}-${S.today}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast(`Đã xuất ${data.rows.length} bản ghi.`);
}
document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
  try{
    if(action==='demo-account'){const f=$('#login-form');f.username.value=id;f.password.value='Demo@12345';return;}
    if(action==='close-modal')return $('#modal').close();
    if(action==='menu')return $('.sidebar').classList.toggle('open');
    if(action==='logout'){await request('/api/logout',{});S=null;return renderLogin();}
    if(action==='tab'){tab=id;page=1;filter='';return render();}
    if(action==='page'){page=Number(id);return render();}
    if(action.startsWith('go-'))return navigate(action.slice(3));
    if(action==='export')return exportData();
    if(action==='print')return window.print();
    if(action==='reset-report'){reportFrom='';reportTo='';reportDept='';return render();}
    if(action==='add-employee')return employeeForm();
    if(action==='edit-employee')return employeeForm(emp(id));
    if(action==='employee-detail')return employeeDetail(emp(id));
    if(action==='archive-employee')return confirmAction('Lưu trữ hồ sơ','Cần chấm dứt hợp đồng và xử lý hết đơn chờ duyệt trước khi lưu trữ. Lịch sử được giữ lại; tài khoản liên kết không thể đăng nhập.','do-archive',id,'Lưu trữ hồ sơ');
    if(action==='do-archive')return await mutate(`/api/employees/${encodeURIComponent(id)}/archive`,{},'POST','Đã lưu trữ hồ sơ.');
    if(action==='restore-employee')return await mutate(`/api/employees/${encodeURIComponent(id)}/restore`,{},'POST','Đã khôi phục hồ sơ.');
    if(action==='department-members'){route='employees';location.hash='employees';setTimeout(()=>{dept=id;render();},0);return;}
    if(action==='add-department')return catalogForm('department');
    if(action==='edit-department')return catalogForm('department',S.departments.find(d=>d.id===id));
    if(action==='add-position')return catalogForm('position');
    if(action==='edit-position')return catalogForm('position',S.positions.find(p=>p.id===id));
    if(action==='delete-department'||action==='delete-position')return confirmAction('Xóa danh mục','Chỉ xóa được danh mục chưa được sử dụng trong hồ sơ và lịch sử.','do-delete-'+action.slice(7),id,'Xóa danh mục');
    if(action==='do-delete-department'||action==='do-delete-position')return await mutate(`/api/${action.endsWith('department')?'departments':'positions'}/${encodeURIComponent(id)}`,{},'DELETE','Đã xóa danh mục.');
    if(action==='add-contract')return contractForm();
    if(action==='contract-detail')return contractDetail(S.contracts.find(c=>c.id===id));
    if(action==='extend-contract'){const c=S.contracts.find(c=>c.id===id);return showModal('Gia hạn hợp đồng',`<p class="notice">${esc(c.id)} · ${esc(employeeName(c.employee_id))}<br>Ngày kết thúc hiện tại: ${fmt(c.end_date)}</p><input type="hidden" name="id" value="${esc(id)}">${input('Ngày kết thúc mới *','new_end_date','','date','required')}${area('Lý do gia hạn *','reason')}`,{form:'extension',submit:'Xác nhận gia hạn'});}
    if(action==='terminate-contract')return showModal('Chấm dứt hợp đồng',`<p class="notice">${esc(id)} · Lịch sử hợp đồng được giữ nguyên sau khi chấm dứt.</p><input type="hidden" name="id" value="${esc(id)}">${input('Ngày chấm dứt *','terminated_date',S.today,'date',`required max="${S.today}"`)}${area('Lý do chấm dứt *','reason')}`,{form:'termination',submit:'Chấm dứt hợp đồng'});
    if(action==='add-assignment')return assignmentForm();
    if(action==='decision-detail'){const d=S.decisions.find(d=>d.id===id);return showModal('Quyết định nhân sự',`<dl class="detail-grid">${[['Số quyết định',d.number],['Loại',d.type],['Ngày ký',fmt(d.signed_date)],['Ngày hiệu lực',fmt(d.effective_date)],['Người ký',d.signer],['Nội dung',d.content]].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`);}
    if(action==='add-leave')return leaveForm();
    if(action==='leave-detail')return leaveDetail(S.leaves.find(l=>l.id===id));
    if(action==='cancel-leave')return confirmAction('Hủy đơn nghỉ phép','Đơn sẽ được chuyển sang trạng thái Đã hủy.','do-cancel-leave',id,'Hủy đơn');
    if(action==='do-cancel-leave')return await mutate(`/api/leaves/${id}/cancel`,{},'POST','Đã hủy đơn nghỉ phép.');
    if(action==='approve-leave'||action==='reject-leave'){const approve=action==='approve-leave';return showModal(approve?'Duyệt đơn nghỉ phép':'Từ chối đơn nghỉ phép',`<p class="notice">${esc(employeeName(S.leaves.find(l=>l.id===id).employee_id))} · ${approve?'Quỹ phép sẽ được kiểm tra trước khi duyệt.':'Nhập lý do để nhân viên biết kết quả.'}</p><input name="id" type="hidden" value="${esc(id)}"><input name="status" type="hidden" value="${approve?'Đã duyệt':'Từ chối'}">${area(approve?'Ghi chú (không bắt buộc)':'Lý do từ chối *','review_note','',!approve)}`,{form:'review',submit:approve?'Xác nhận duyệt':'Xác nhận từ chối'});}
    if(action==='edit-balance'){const b=S.balances.find(b=>b.employee_id===id&&b.year===Number(leaveYear||S.today.slice(0,4)));return showModal('Điều chỉnh quỹ phép',`<p class="notice">${esc(employeeName(id))} · Đã dùng ${b.used} ngày. Tổng phép mới phải từ số ngày đã dùng trở lên.</p><input type="hidden" name="employee_id" value="${esc(id)}"><div class="form-grid">${input('Năm','year',b.year,'number','required min="2000" max="2100"')}${input('Tổng ngày phép *','total',b.total,'number',`required min="${b.used}" max="366" step="1"`)}</div>`,{form:'balance'});}
    if(action==='change-password')return showModal('Đổi mật khẩu',`${input('Mật khẩu hiện tại *','current_password','','password','required autocomplete="current-password"')}${input('Mật khẩu mới *','new_password','','password','required minlength="10" autocomplete="new-password"')}<p class="notice">Tối thiểu 10 ký tự. Sau khi đổi mật khẩu, mọi phiên của tài khoản sẽ đăng xuất.</p>`,{form:'password',submit:'Đổi mật khẩu'});
    if(action==='add-user')return showModal('Tạo tài khoản',`<div class="form-grid">${input('Tên đăng nhập *','username','','text','required minlength="3" maxlength="50" autocomplete="off"')}${select('Nhân viên *','employee_id',options(activeEmployees(),''),'required')}${select('Vai trò *','role',Object.entries(roleNames).map(([id,name])=>`<option value="${id}" ${id==='employee'?'selected':''}>${name}</option>`).join(''))}${input('Mật khẩu ban đầu *','password','','password','required minlength="10" autocomplete="new-password"')}</div>`,{form:'user'});
    if(action==='toggle-user')return confirmAction('Đổi trạng thái tài khoản','Khóa tài khoản sẽ kết thúc các phiên đăng nhập của tài khoản đó.','do-toggle-user',id);
    if(action==='do-toggle-user')return await mutate(`/api/users/${id}/toggle`,{},'POST','Đã cập nhật trạng thái tài khoản.');
  }catch(error){const box=$('#modal-error');if($('#modal').open&&box)box.textContent=error.message;else toast(error.message,true);}
});
document.addEventListener('submit',async event=>{
  event.preventDefault();const f=event.target,body=Object.fromEntries(new FormData(f));const submit=f.querySelector('[type="submit"]');
  if(f.getAttribute('id')==='global-search'){search=body.q;tab='active';dept='';filter='';page=1;if(route==='employees')render();else{location.hash='employees';setTimeout(()=>{search=body.q;render();},0);}return;}
  if(submit)submit.disabled=true;
  try{
    if(f.getAttribute('id')==='login-form'){await request('/api/login',body);tab='';await refresh();return;}
    if(f.getAttribute('id')!=='modal-form')return;
    const kind=f.dataset.kind;
    if(kind==='employee'){
      const edit=body.editing;delete body.editing;
      if(edit){body.department_id=emp(edit).department_id;body.position_id=emp(edit).position_id;await mutate('/api/employees/'+encodeURIComponent(edit),body,'PUT','Đã lưu hồ sơ nhân viên.');}
      else{
        const result=await request('/api/employees',body);await refresh();
        showModal('Đã tạo nhân viên và tài khoản',`<p class="notice">Đã lưu hồ sơ <strong>${esc(result.id)}</strong>. Gửi thông tin dưới đây cho nhân viên để đăng nhập. Mật khẩu ban đầu chỉ hiển thị trong lần tạo này.</p><dl class="detail-grid"><div><dt>Tên đăng nhập</dt><dd><strong>${esc(result.account.username)}</strong></dd></div><div><dt>Mật khẩu ban đầu</dt><dd><code>${esc(result.account.initial_password)}</code></dd></div><div><dt>Vai trò</dt><dd>Nhân viên</dd></div></dl><p class="notice">Nhân viên có thể đổi mật khẩu tại Tài khoản của tôi sau khi đăng nhập. Hãy lưu lại thông tin trước khi đóng cửa sổ này.</p>`);
      }
    }
    if(kind==='department'||kind==='position'){const edit=body.editing;delete body.editing;await mutate(`/api/${kind==='department'?'departments':'positions'}${edit?'/'+encodeURIComponent(edit):''}`,body,edit?'PUT':'POST');}
    if(kind==='contract')await mutate('/api/contracts',body,'POST','Đã lập hợp đồng.');
    if(kind==='extension')await mutate(`/api/contracts/${encodeURIComponent(body.id)}/extend`,body,'POST','Đã gia hạn hợp đồng và lưu lịch sử.');
    if(kind==='termination')await mutate(`/api/contracts/${encodeURIComponent(body.id)}/terminate`,body,'POST','Đã chấm dứt hợp đồng.');
    if(kind==='assignment')await mutate('/api/assignments',body,'POST','Đã lưu quyết định và cập nhật hồ sơ.');
    if(kind==='leave')await mutate('/api/leaves',body,'POST','Đã gửi đơn nghỉ phép.');
    if(kind==='review')await mutate(`/api/leaves/${body.id}/review`,body,'POST','Đã xử lý đơn nghỉ phép.');
    if(kind==='balance')await mutate('/api/balances',body,'POST','Đã cập nhật quỹ phép.');
    if(kind==='user')await mutate('/api/users',body,'POST','Đã tạo tài khoản.');
    if(kind==='password'){await request('/api/password',body);S=null;renderLogin();toast('Đã đổi mật khẩu. Vui lòng đăng nhập lại.');}
  }catch(error){const errorEl=f.getAttribute('id')==='login-form'?$('#login-error'):$('#modal-error');if(errorEl)errorEl.textContent=error.message;else toast(error.message,true);}
  finally{if(submit)submit.disabled=false;}
});
document.addEventListener('input',event=>{if(event.target.id==='list-search'){search=event.target.value;page=1;const pos=event.target.selectionStart;render();const target=$('#list-search');target.focus();target.setSelectionRange(pos,pos);}});
document.addEventListener('change',event=>{
  const id=event.target.id,v=event.target.value; if(id==='leave-year'){if(Number(v)>=2000&&Number(v)<=2100){leaveYear=v;render();}return;}
  if(id==='department-filter'){dept=v;page=1;render();}if(id==='status-filter'){filter=v;page=1;render();}
  if(id==='report-type'){reportType=v;render();}if(id==='report-dept'){reportDept=v;render();}
  if(id==='report-from'||id==='report-to'){const from=id==='report-from'?v:reportFrom,to=id==='report-to'?v:reportTo;if(from&&to&&from>to){toast('Từ ngày không được sau đến ngày.',true);event.target.value=id==='report-from'?reportFrom:reportTo;return;}reportFrom=from;reportTo=to;render();}
  if(event.target.name==='type'&&$('#modal-form')?.dataset.kind==='contract'){const field=$('#modal-form [name="end_date"]');field.disabled=v==='Không xác định thời hạn';field.required=!field.disabled;if(field.disabled)field.value='';}
});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'dashboard';tab='';search='';dept='';filter='';page=1;if(S)render();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
try{await refresh();}catch(error){renderLogin();if(error.message!=='Vui lòng đăng nhập.'&&error.message!=='Phiên đăng nhập đã hết hạn.')toast('Không thể kết nối máy chủ. Vui lòng tải lại trang.',true);}
